class No {
    constructor(valor) {
        this.valor = valor;
        this.esquerda = null;
        this.direita = null;
    }
}

function buscaValor(no, valor) {
    if (no === null) {
        return false;
    }
    if (no.valor === valor) {
        return true;
    }
    return buscaValor(no.esquerda, valor) || buscaValor(no.direita, valor);
}

const raiz = new No(10);
raiz.esquerda = new No(5);
raiz.direita = new No(15);

console.log(buscaValor(raiz, 20));

def bubble_sort(arr):
    n = len(arr)
    for i in range(n):
        for j in range(0, n-i-1):
            if arr[j] > arr[j+1]:
                arr[j], arr[j+1] = arr[j+1], arr[j]
    return arr

